n = int(input())
edges={'A':[('C',2)],'C':[('B',2)],'B':[]} if n==1 else {'A':[('B',1)],'B':[]}
dist={'A':0};todo=[(0,'A')]
import heapq
while todo:
 cost,node=heapq.heappop(todo)
 if cost!=dist[node]:continue
 for target,weight in edges[node]:
  value=cost+weight
  if value<dist.get(target,999):dist[target]=value;heapq.heappush(todo,(value,target))
print(1)

